def revcomp(s):
    return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

def find_orfs(s, minlen):
    """Return (start_idx0, end_idx0_exclusive, strand, frame, prot)"""
    orfs = []
    L = len(s)
    for strand, ss in (('+', s), ('-', revcomp(s))):
        for frame in range(3):
            i = frame
            while i + 3 <= L:
                if ss[i:i+3] == 'ATG':
                    for j in range(i, L-2, 3):
                        if ss[j:j+3] in ('TAA','TAG','TGA'):
                            if (j+3-i) >= minlen:
                                prot = ''.join(codon_table[ss[k:k+3]] for k in range(i, j+3, 3))
                                orfs.append((i, j+3, strand, frame, prot, ss[i:j+3]))
                            i_stop = j
                            break
                    else:
                        # runs to end without stop
                        pass
                    # continue scanning after 3 bases regardless
                i += 3
    return orfs

